7: import { google, Auth } from 'googleapis';
8: import crypto from 'node:crypto';
9: import * as http from 'node:http';
10: import * as net from 'node:net';
11: import * as url from 'node:url';
12: import { logToFile } from '../utils/logger';
13: import open from '../utils/open-wrapper';
14: import { shouldLaunchBrowser } from '../utils/secure-browser-launcher';
15: import { OAuthCredentialStorage } from './token-storage/oauth-credential-storage';
16: import { loadConfig } from '../utils/config';
17: 
18: const config = loadConfig();
19: const CLIENT_ID = config.clientId;
20: const CLOUD_FUNCTION_URL = config.cloudFunctionUrl;
21: const TOKEN_EXPIRY_BUFFER_MS = 5 * 60 * 1000; // 5 minutes
22: 
23: /**
24:  * An Authentication URL for updating the credentials of a Oauth2Client
25:  * as well as a promise that will resolve when the credentials have
26:  * been refreshed (or which throws error when refreshing credentials failed).
27:  */
28: interface OauthWebLogin {
29:   authUrl: string;
30:   loginCompletePromise: Promise<void>;
31: }
32: 
33: export class AuthManager {
34:   private client: Auth.OAuth2Client | null = null;
35:   private scopes: string[];
36:   private onStatusUpdate: ((message: string) => void) | null = null;
37: 
38:   constructor(scopes: string[]) {
39:     this.scopes = scopes;
40:   }
41: 
42:   public setOnStatusUpdate(callback: (message: string) => void) {
43:     this.onStatusUpdate = callback;
44:   }
45: 
46:   private isTokenExpiringSoon(credentials: Auth.Credentials): boolean {
47:     return !!(
48:       credentials.expiry_date &&
49:       credentials.expiry_date < Date.now() + TOKEN_EXPIRY_BUFFER_MS
50:     );
51:   }
52: 
53:   private async loadCachedCredentials(
54:     client: Auth.OAuth2Client,
55:   ): Promise<boolean> {
56:     const credentials = await OAuthCredentialStorage.loadCredentials();
57: 
58:     if (credentials) {
59:       // Check if saved token has required scopes
60:       const savedScopes = new Set(credentials.scope?.split(' ') ?? []);
61:       logToFile(`Cached token has scopes: ${[...savedScopes].join(', ')}`);
62:       logToFile(`Required scopes: ${this.scopes.join(', ')}`);
63: 
64:       const missingScopes = this.scopes.filter(
65:         (scope) => !savedScopes.has(scope),
66:       );
67: 
68:       if (missingScopes.length > 0) {
69:         logToFile(
70:           `Token cache missing required scopes: ${missingScopes.join(', ')}`,
71:         );
72:         logToFile('Removing cached token to force re-authentication...');
73:         await OAuthCredentialStorage.clearCredentials();
74:         return false;
75:       } else {
76:         client.setCredentials(credentials);
77:         return true;
78:       }
79:     }
80: 
81:     return false;
82:   }
83: 
84:   public async getAuthenticatedClient(): Promise<Auth.OAuth2Client> {
85:     logToFile('getAuthenticatedClient called');
86: 
87:     // Check if we have a cached client with valid credentials
88:     if (
89:       this.client &&
90:       this.client.credentials &&
91:       this.client.credentials.refresh_token
92:     ) {
93:       logToFile('Returning existing cached client with valid credentials');
94:       logToFile(
95:         `Access token exists: ${!!this.client.credentials.access_token}`,
96:       );
97:       logToFile(`Expiry date: ${this.client.credentials.expiry_date}`);
98:       logToFile(`Current time: ${Date.now()}`);
99: 
100:       const isExpired = this.isTokenExpiringSoon(this.client.credentials);
101:       logToFile(`Token expired: ${isExpired}`);
102: 
103:       // Proactively refresh if expired
104:       if (isExpired) {
105:         logToFile('Token is expired, refreshing proactively...');
106:         try {
107:           await this.refreshToken();
108:           logToFile('Token refreshed successfully');
109:         } catch (error) {
110:           logToFile(`Failed to refresh token: ${error}`);
111:           // Clear the client and fall through to re-authenticate
112:           this.client = null;
113:           await OAuthCredentialStorage.clearCredentials();
114:         }
115:       }
116: 
117:       // Return the client (either still valid or just refreshed)
118:       if (this.client) {
119:         return this.client;
120:       }
121:     }
122: 
123:     // Note: No clientSecret is provided here. The secret is only known by the cloud function.
124:     const options: Auth.OAuth2ClientOptions = {
125:       clientId: CLIENT_ID,
126:     };
127:     const oAuth2Client = new google.auth.OAuth2(options);
128: 
129:     oAuth2Client.on('tokens', async (tokens) => {
130:       logToFile('Tokens refreshed event received');
131:       if (tokens.refresh_token) {
132:         logToFile('New refresh token received in event');
133:       }
134: 
135:       try {
136:         // Create a copy to preserve refresh_token from storage
137:         const current = (await OAuthCredentialStorage.loadCredentials()) || {};
138:         const merged = {
139:           ...tokens,
140:           refresh_token: tokens.refresh_token || current.refresh_token,
141:         };
142:         await OAuthCredentialStorage.saveCredentials(merged);
143:         logToFile('Credentials saved after refresh');
144:       } catch (e) {
145:         logToFile(`Error saving refreshed credentials: ${e}`);
146:       }
147:     });
148: 
149:     logToFile('No valid cached client, checking for saved credentials...');
150:     if (await this.loadCachedCredentials(oAuth2Client)) {
151:       logToFile('Loaded saved credentials, caching and returning client');
152:       this.client = oAuth2Client;
153: 
154:       // Check if the loaded token is expired and refresh proactively
155:       const isExpired = this.isTokenExpiringSoon(this.client.credentials);
156:       logToFile(`Token expired: ${isExpired}`);
157: 
158:       if (isExpired) {
159:         logToFile('Loaded token is expired, refreshing proactively...');
160:         try {
161:           await this.refreshToken();
162:           logToFile('Token refreshed successfully after loading from storage');
163:         } catch (error) {
164:           logToFile(`Failed to refresh loaded token: ${error}`);
165:           // Clear the client and fall through to re-authenticate
166:           this.client = null;
167:           await OAuthCredentialStorage.clearCredentials();
168:         }
169:       }
170: 
171:       // Return the client if refresh succeeded or token was still valid
172:       if (this.client) {
173:         return this.client;
174:       }
175:     }
176: 
177:     const webLogin = await this.authWithWeb(oAuth2Client);
178:     await open(webLogin.authUrl);
179:     const msg = 'Waiting for authentication... Check your browser.';
180:     logToFile(msg);
181:     if (this.onStatusUpdate) {
182:       this.onStatusUpdate(msg);
183:     }
184: 
185:     // Add timeout to prevent infinite waiting when browser tab gets stuck
186:     const authTimeout = 5 * 60 * 1000; // 5 minutes timeout
187:     const timeoutPromise = new Promise<never>((_, reject) => {
188:       setTimeout(() => {
189:         reject(
190:           new Error(
191:             'User is not authenticated. Authentication timed out after 5 minutes. The user did not complete the login process in the browser. ' +
192:               'Please ask the user to check their browser and try again.',
193:           ),
194:         );
195:       }, authTimeout);
196:     });
197:     await Promise.race([webLogin.loginCompletePromise, timeoutPromise]);
198: 
199:     await OAuthCredentialStorage.saveCredentials(oAuth2Client.credentials);
200:     this.client = oAuth2Client;
201:     return this.client;
202:   }
203: 
204:   public async clearAuth(): Promise<void> {
205:     logToFile('Clearing authentication...');
206:     this.client = null;
207:     await OAuthCredentialStorage.clearCredentials();
208:     logToFile('Authentication cleared.');
209:   }
210: 
211:   public async refreshToken(): Promise<void> {
212:     logToFile('Manual token refresh triggered');
213:     if (!this.client) {
214:       logToFile('No client available to refresh, getting new client');
215:       this.client = await this.getAuthenticatedClient();
216:     }
217:     try {
218:       const currentCredentials = { ...this.client.credentials };
219: 
220:       if (!currentCredentials.refresh_token) {
221:         throw new Error('No refresh token available');
222:       }
223: 
224:       logToFile('Calling cloud function to refresh token...');
225: 
226:       // Call the cloud function refresh endpoint
227:       // The cloud function has the client secret needed for token refresh
228:       const response = await fetch(`${CLOUD_FUNCTION_URL}/refreshToken`, {
229:         method: 'POST',
230:         headers: {
231:           'Content-Type': 'application/json',
232:         },
233:         body: JSON.stringify({
234:           refresh_token: currentCredentials.refresh_token,
235:         }),
236:       });
237: 
238:       if (!response.ok) {
239:         const errorText = await response.text();
240:         throw new Error(
241:           `Token refresh failed: ${response.status} ${errorText}`,
242:         );
243:       }
244: 
245:       const newTokens = await response.json();
246: 
247:       // Merge new tokens with existing credentials, preserving refresh_token
248:       // Note: Google does NOT return a new refresh_token on refresh
249:       const mergedCredentials = {
250:         ...newTokens,
251:         refresh_token: currentCredentials.refresh_token, // Always preserve original
252:       };
253: 
254:       this.client.setCredentials(mergedCredentials);
255:       await OAuthCredentialStorage.saveCredentials(mergedCredentials);
256:       logToFile('Token refreshed and saved successfully via cloud function');
257:     } catch (error) {
258:       logToFile(`Error during token refresh: ${error}`);
259:       throw error;
260:     }
261:   }
262: 
263:   private async getAvailablePort(): Promise<number> {
264:     return new Promise((resolve, reject) => {
265:       let port = 0;
266:       try {
267:         const portStr = process.env['OAUTH_CALLBACK_PORT'];
268:         if (portStr) {
269:           port = parseInt(portStr, 10);
270:           if (isNaN(port) || port <= 0 || port > 65535) {
271:             return reject(
272:               new Error(`Invalid value for OAUTH_CALLBACK_PORT: "${portStr}"`),
273:             );
274:           }
275:           return resolve(port);
276:         }
277:         const server = net.createServer();
278:         server.listen(0, () => {
279:           const address = server.address()! as net.AddressInfo;
280:           port = address.port;
281:         });
282:         server.on('listening', () => {
283:           server.close();
284:           server.unref();
285:         });
286:         server.on('error', (e) => reject(e));
287:         server.on('close', () => resolve(port));
288:       } catch (e) {
289:         reject(e);
290:       }
291:     });
292:   }
293: 
294:   private async authWithWeb(client: Auth.OAuth2Client): Promise<OauthWebLogin> {
295:     logToFile(
296:       `Requesting authentication with scopes: ${this.scopes.join(', ')}`,
297:     );
298: 
299:     const port = await this.getAvailablePort();
300:     const host = process.env['OAUTH_CALLBACK_HOST'] || 'localhost';
301: 
302:     const localRedirectUri = `http://${host}:${port}/oauth2callback`;
303: 
304:     const isGuiAvailable = shouldLaunchBrowser();
305: 
306:     // SECURITY: Generate a random token for CSRF protection.
307:     const csrfToken = crypto.randomBytes(32).toString('hex');
308: 
309:     // The state now contains a JSON payload indicating the flow mode and CSRF token.
310:     const statePayload = {
311:       uri: isGuiAvailable ? localRedirectUri : undefined,
312:       manual: !isGuiAvailable,
