const createMockChildProcess = () => ({
  unref: () => {},
  ref: () => {},
  pid: 123,
  stdout: null,
  stderr: null,
  stdin: null,
  channel: null,
  connected: false,
  exitCode: 0,
  killed: false,
  signalCode: null,
  spawnargs: [],
  spawnfile: '',
});

const openWrapper = async (url: string): Promise<any> => {
  // Check if we should launch the browser
  if (!shouldLaunchBrowser()) {
