  private async handleErrors<T>(
    fn: () => Promise<T>,
  ): Promise<{ content: [{ type: 'text'; text: string }] }> {
    try {
      const result = await fn();
      return {
        content: [
          {
            type: 'text' as const,
            text: JSON.stringify(result),
          },
        ],
      };
